CREATE MATERIALIZED VIEW realy.decisions_mv TO realy.decisions AS
SELECT
  event_id, revision,
  `event.customer_id` AS customer_id, `event.card_id` AS card_id, `event.merchant_id` AS merchant_id,
  `event.payee_id` AS payee_id, `event.device_id` AS device_id,
  fromUnixTimestamp64Micro(`event.event_time_us`) AS event_time,
  fromUnixTimestamp64Micro(decided_at_us) AS decided_at,
  arrayElement(['UNSPECIFIED', 'CARD_PURCHASE', 'ATM_WITHDRAWAL', 'TRANSFER', 'CARD_REFUND'], toInt32(`event.payment_type`) + 1) AS payment_type,
  arrayElement(['UNSPECIFIED', 'POS', 'ECOM', 'ATM', 'MOTO', 'IN_APP', 'ONLINE_BANKING'], toInt32(`event.channel`) + 1) AS channel,
  arrayElement(['UNSPECIFIED', 'CHIP', 'CONTACTLESS', 'MAGSTRIPE', 'MANUAL', 'WALLET_TOKEN', 'ECOM_3DS', 'ECOM_NON_3DS', 'CREDENTIAL_ON_FILE', 'BANK_APP'], toInt32(`event.entry_mode`) + 1) AS entry_mode,
  `event.mcc` AS mcc, `event.merchant_country` AS merchant_country, `event.amount_usd_minor` AS amount_usd_minor,
  arrayElement(['OUTCOME_UNSPECIFIED', 'APPROVE', 'REVIEW', 'DECLINE', 'CHALLENGE'], toInt32(outcome) + 1) AS outcome, score, reason_codes,
  arrayElement(['FULL', 'RULES_ONLY_FALLBACK', 'PROVISIONAL', 'FINAL_AFTER_PROVISIONAL', 'ECHO'], toInt32(path) + 1) AS path, degraded,
  arrayElement(['UNSPECIFIED', 'SYNC_GRPC', 'SYNC_HTTP', 'ASYNC_KAFKA_GATEWAY', 'ASYNC_FLINK_INLINE'], toInt32(ingress_mode) + 1) AS ingress_mode, instance_id, policy_version, rule_set_version,
  `model.model_name` AS model_name, `model.model_version` AS model_version, `model.input_hash` AS model_input_hash,
  `model.timed_out` AS model_timed_out, `model.batch_size` AS model_batch_size,
  feature_schema_version, `features.values` AS features_raw, `features.missing_bitmap` AS features_missing,
  `features.values`[1] AS `f_cust_count_1h`,
  `features.values`[2] AS `f_cust_count_24h`,
  `features.values`[3] AS `f_cust_amount_sum_24h`,
  `features.values`[4] AS `f_cust_amount_avg_30d`,
  `features.values`[5] AS `f_cust_distinct_countries_24h`,
  `features.values`[6] AS `f_cust_device_novel`,
  `features.values`[7] AS `f_cust_payee_novel`,
  `features.values`[8] AS `f_cust_ip_country_novel`,
  `features.values`[9] AS `f_cust_transfer_count_1h`,
  `features.values`[10] AS `f_cust_transfer_sum_24h`,
  `features.values`[11] AS `f_card_count_1m`,
  `features.values`[12] AS `f_card_count_5m`,
  `features.values`[13] AS `f_card_count_1h`,
  `features.values`[14] AS `f_card_count_24h`,
  `features.values`[15] AS `f_card_amount_sum_1h`,
  `features.values`[16] AS `f_card_amount_sum_24h`,
  `features.values`[17] AS `f_card_amount_max_7d`,
  `features.values`[18] AS `f_card_small_cnp_count_10m`,
  `features.values`[19] AS `f_card_distinct_merchants_10m`,
  `features.values`[20] AS `f_card_distinct_merchants_24h`,
  `features.values`[21] AS `f_card_contactless_count_30m`,
  `features.values`[22] AS `f_card_contactless_sum_30m`,
  `features.values`[23] AS `f_card_atm_count_1h`,
  `features.values`[24] AS `f_card_atm_sum_24h`,
  `features.values`[25] AS `f_card_geo_speed_kmh`,
  `features.values`[26] AS `f_card_secs_since_last`,
  `features.values`[27] AS `f_dev_count_5m`,
  `features.values`[28] AS `f_dev_distinct_cards_1h`,
  `features.values`[29] AS `f_dev_distinct_customers_24h`,
  `features.values`[30] AS `f_ip_count_5m`,
  `features.values`[31] AS `f_ip_distinct_cards_1h`,
  `features.values`[32] AS `f_merch_count_1m`,
  `features.values`[33] AS `f_merch_small_cnp_count_5m`,
  `features.values`[34] AS `f_merch_amount_sum_1h`,
  `features.values`[35] AS `f_term_count_5m`,
  `features.values`[36] AS `f_term_atm_sum_1h`,
  `features.values`[37] AS `f_payee_inbound_count_1h`,
  `features.values`[38] AS `f_payee_inbound_sum_24h`,
  `features.values`[39] AS `f_payee_distinct_senders_24h`,
  `features.values`[40] AS `f_cust_tenure_days`,
  `features.values`[41] AS `f_cust_segment`,
  `features.values`[42] AS `f_cust_avg_ticket_usd`,
  `features.values`[43] AS `f_merch_risk_tier`,
  `features.values`[44] AS `f_merch_fraud_rate_30d`,
  `features.values`[45] AS `f_amount_usd`,
  `features.values`[46] AS `f_is_cnp`,
  `features.values`[47] AS `f_is_contactless`,
  `features.values`[48] AS `f_is_atm`,
  `features.values`[49] AS `f_is_transfer`,
  `features.values`[50] AS `f_is_foreign`,
  `features.values`[51] AS `f_dist_from_home_km`,
  `features.values`[52] AS `f_amount_to_avg_ratio`,
  `features.values`[53] AS `f_local_hour`,
  `features.values`[54] AS `f_credit_utilisation_24h`,
  `features.values`[55] AS `f_cvv_mismatch`,
  `features.values`[56] AS `f_avs_mismatch`,
  `features.values`[57] AS `f_three_ds_authenticated`,
  `features.values`[58] AS `f_pin_verified`,
  `features.values`[59] AS `f_cryptogram_missing`,
  `features.values`[60] AS `f_scheme_score`,
  `features.values`[61] AS `f_card_cvv_fail_count_1h`,
  `features.values`[62] AS `f_merch_cvv_fail_count_5m`,
  `trace.run_id` AS run_id, `trace.gen_id` AS gen_id, `trace.seq` AS seq,
  `trace.t_intended_us` AS t_intended_us, `trace.t_sent_us` AS t_sent_us,
  toInt32(arraySum(arrayFilter((d, s) -> s = 11, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_queue_wait_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 12, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_deserialize_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 20, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_shuffle_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 21, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_state_features_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 30, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_feature_lookup_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 31, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_feature_assemble_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 40, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_model_call_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 41, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_model_batch_wait_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 42, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_model_server_queue_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 43, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_model_server_compute_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 50, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_rules_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 51, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_policy_us`,
  toInt32(arraySum(arrayFilter((d, s) -> s = 81, `trace.spans.dur_us`, `trace.spans.stage`))) AS `lat_async_wait_us`,
  toInt32(arrayFirst((st, s) -> s = 70, `trace.spans.start_us`, `trace.spans.stage`)
          - arrayFirst((st, s) -> s = 10, `trace.spans.start_us`, `trace.spans.stage`)) AS hot_path_us,
  assumeNotNull(_timestamp_ms) AS appended_at,
  toInt32(greatest(0, toUnixTimestamp64Milli(assumeNotNull(_timestamp_ms)) * 1000 - decided_at_us)) AS lat_audit_append_us,
  `rule_hits.rule_id` AS rule_ids,
  arrayMap(a -> arrayElement(['OUTCOME_UNSPECIFIED', 'APPROVE', 'REVIEW', 'DECLINE', 'CHALLENGE'], toInt32(a) + 1), `rule_hits.action`) AS rule_actions,
  arrayMap(e -> arrayElement(['UNSPECIFIED', 'CUSTOMER', 'CARD', 'DEVICE', 'IP', 'MERCHANT', 'TERMINAL', 'PAYEE'], toInt32(e) + 1), `features.freshness.entity`) AS fresh_entity,
  arrayMap(u -> if(u > 0, decided_at_us - u, -1), `features.freshness.updated_at_us`) AS fresh_age_us,
  `features.freshness.found` AS fresh_found
FROM realy.decisions_queue WHERE length(_error) = 0;
